  if (globalFilters.companyId) {\n    const activeCompany = companies.find(c => c.id.toString() === globalFilters.companyId?.toString());\n    if (activeCompany) {\n      return (\n        <div className="w-full mx-auto pb-12 flex flex-col gap-6 animate-in fade-in duration-500 relative px-4 sm:px-6 lg:px-10">\n          <div className="flex items-center gap-2 mb-4 text-[#64748B] text-sm cursor-pointer hover:text-[#111111]" onClick={() => setGlobalFilters({})}>\n            <ChevronLeft size={16} />\n            Voltar para Empresas\n          </div>\n          <Vision360\n            entityType="company"\n            entityId={activeCompany.id}\n            entityName={activeCompany.name}\n            entityData={activeCompany}\n          />\n        </div>\n      );\n    }\n  }\n' src/components/EmpresasView.tsx
